<?php
declare(strict_types=1);require_once __DIR__.'/database.php';$message='';$success=false;$count=0;try{$db=database();$count=(int)$db->query('SELECT COUNT(*) FROM users')->fetchColumn();if($count>0)$message='تم إعداد النظام مسبقًا. احذف setup.php بعد التأكد من تسجيل الدخول.';elseif(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){$u=trim((string)($_POST['username']??'admin'));$p=(string)($_POST['password']??'');$c=(string)($_POST['password_confirmation']??'');if($u===''||strlen($u)>64)$message='اسم المستخدم غير صحيح.';elseif(strlen($p)<8)$message='كلمة المرور يجب ألا تقل عن 8 خانات.';elseif($p!==$c)$message='تأكيد كلمة المرور غير مطابق.';else{$s=$db->prepare("INSERT INTO users(username,role,password_hash) VALUES(:u,'admin',:p)");$s->execute(['u'=>$u,'p'=>password_hash($p,PASSWORD_DEFAULT)]);$success=true;$message='تم إنشاء حساب المدير. احذف setup.php بعد تسجيل الدخول.';}}}catch(Throwable $e){error_log($e->__toString());$message='تعذر الاتصال بقاعدة البيانات. راجع الإعدادات والاستيراد.';}?><!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>الإعداد الأولي</title><style>body{font-family:Tahoma;background:#eef6f9;display:grid;place-items:center;min-height:100vh}main{background:#fff;padding:28px;border-radius:16px;width:min(90%,460px)}input,button,a{box-sizing:border-box;width:100%;padding:12px;margin-top:10px}button,a{background:#16835e;color:#fff;border:0;text-align:center;display:block;text-decoration:none}</style><main><h1>الإعداد الأولي</h1><?php if($message):?><p><?=htmlspecialchars($message,ENT_QUOTES,'UTF-8')?></p><?php endif;?><?php if(!$success&&$count===0):?><form method="post"><input name="username" value="admin" required><input name="password" type="password" minlength="8" placeholder="كلمة المرور" required><input name="password_confirmation" type="password" minlength="8" placeholder="تأكيد كلمة المرور" required><button>إنشاء حساب المدير</button></form><?php else:?><a href="index.html">تسجيل الدخول</a><?php endif;?></main></html>
